ALTER TABLE "search_pending_refreshes" ADD COLUMN "cascade_phase" text;--> statement-breakpoint
ALTER TABLE "search_pending_refreshes" ADD COLUMN "cascade_cursor" text;--> statement-breakpoint
ALTER TABLE "search_pending_refreshes" ADD CONSTRAINT "search_pending_refreshes_cascade_check" CHECK (("search_pending_refreshes"."cascade_phase" is null and "search_pending_refreshes"."cascade_cursor" is null) or ("search_pending_refreshes"."cascade_phase" is not null and "search_pending_refreshes"."resource_kind" in ('list', 'space') and "search_pending_refreshes"."cascade_phase" in ('indexed', 'tasks', 'lists', 'self') and ("search_pending_refreshes"."cascade_phase" <> 'lists' or "search_pending_refreshes"."resource_kind" = 'space') and ("search_pending_refreshes"."cascade_cursor" is null or ("search_pending_refreshes"."cascade_phase" <> 'self' and length("search_pending_refreshes"."cascade_cursor") between 1 and 1024))));